const enfermedadData=[{"disease":"Las notificaciones del chat dejaron de llegar y nadie se enteró","characteristic":"La función leía con la clave anónima y recibía cero filas sin error","opts":["La función leía con la clave anónima y recibía cero filas sin error","Los teléfonos perdieron la conexión","El servicio de notificaciones se cayó","Los mensajes tardaban demasiado"]},{"disease":"La aplicación quedó envenenada y recargar no la arreglaba","characteristic":"El service worker guardó la pantalla de acceso como si fuera app.js","opts":["El service worker guardó la pantalla de acceso como si fuera app.js","El archivo app.js estaba mal escrito","La caché se llenó de archivos viejos","El teléfono se quedó sin memoria"]},{"disease":"La casa parecía cerrada y entraba cualquiera que pidiera una cuenta","characteristic":"La política comprobaba que hubiera sesión, no que fuera de la familia","opts":["La política comprobaba que hubiera sesión, no que fuera de la familia","Las contraseñas eran demasiado cortas","La clave pública estaba en el navegador","Faltaba activar la seguridad por fila"]},{"disease":"Un documento bien guardado desapareció al fallar la red","characteristic":"El barrido confundió «no llegó la confirmación» con «no se guardó»","opts":["El barrido confundió «no llegó la confirmación» con «no se guardó»","El archivo se subió incompleto","El depósito estaba lleno","La ficha se creó dos veces"]},{"disease":"El editor dijo «Success» y la tabla se quedó vacía","characteristic":"Las comprobaciones solo avisaban, así que ninguna podía detener nada","opts":["Las comprobaciones solo avisaban, así que ninguna podía detener nada","El bloque se ejecutó dos veces","Los correos estaban mal escritos","La tabla no se había creado"]},{"disease":"Se dio por cerrada una casa que seguía abierta","characteristic":"La prueba se hizo con sesión iniciada, así que no podía salir mal","opts":["La prueba se hizo con sesión iniciada, así que no podía salir mal","La prueba se hizo demasiado rápido","Se probó en el teléfono equivocado","Faltaba borrar la caché del navegador"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"La línea donde el dato deja de ser tuyo.","type":"Frontera de confianza"},{"s":"Comprobar que un dato es lo que dice ser antes de usarlo.","type":"Validación"},{"s":"Se escribe lo que sí se acepta y lo demás se rechaza.","type":"Lista permitida"},{"s":"Solo detiene lo que ya se le ocurrió a alguien.","type":"Lista prohibida"},{"s":"Cuánto, cuántas veces, hasta cuándo y hasta dónde.","type":"Límite"},{"s":"Un dato que termina ejecutándose como una orden.","type":"Inyección"},{"s":"La instrucción va aparte y el dato viaja en su casilla.","type":"Consulta con parámetros"},{"s":"Ante lo que no se puede comprobar, la salida que no hace daño.","type":"Fallar cerrado"},{"s":"La operación sale mal y nadie se entera.","type":"Fallar en silencio"},{"s":"El resultado vacío que hay que tratar como pregunta.","type":"Cero sospechoso"}];
const classifyTaskDB=[{"w":"Lo escrito en un formulario","gen":"Origen","n":"De fuera","g":"Cruza la frontera","t":"Se comprueba entero"},{"w":"Una constante del propio código","gen":"Origen","n":"De dentro","g":"Nace en casa","t":"No la escribió nadie de fuera"},{"w":"Que el correo tenga forma de correo","gen":"Defensa","n":"Forma","g":"Validar","t":"Mira qué es el dato"},{"w":"Cinco intentos por minuto","gen":"Defensa","n":"Cantidad","g":"Limitar","t":"Mira cuánto y cuántas veces"},{"w":"Consulta con parámetros","gen":"Defensa","n":"Separación","g":"Separar","t":"El dato no puede cambiar la orden"},{"w":"Armar la consulta pegando texto","gen":"Fallo","n":"Mezcla","g":"Inyección","t":"El dato se vuelve instrucción"},{"w":"Cero filas sin error","gen":"Fallo","n":"Silencio","g":"Fallar en silencio","t":"Nadie se entera de que salió mal"},{"w":"Parar cuando no se puede comprobar","gen":"Defensa","n":"Salida segura","g":"Fallar cerrado","t":"Ante la duda, no se hace daño"},{"w":"Un aviso al panel que nadie mira","gen":"Fallo","n":"Silencio","g":"Fallar en silencio","t":"Avisar no es detener"},{"w":"Romper la prueba a propósito","gen":"Defensa","n":"Confianza","g":"Validar la prueba","t":"Solo se cree lo que ya dijo que no"}];
const completeTaskDB=[{"s":"Comprobar que un dato es lo que dice ser es ___.","opts":["validarlo","copiarlo","cifrarlo"],"ans":"validarlo"},{"s":"La lista que dice lo que sí entra es la lista ___.","opts":["permitida","prohibida","completa"],"ans":"permitida"},{"s":"La validación que cuenta es la del ___.","opts":["servidor","navegador","teclado"],"ans":"servidor"},{"s":"Un dato que se ejecuta como orden es una ___.","opts":["inyección","copia","consulta"],"ans":"inyección"},{"s":"El dato viaja aparte en la consulta con ___.","opts":["parámetros","comillas","espacios"],"ans":"parámetros"},{"s":"Ante lo que no se puede comprobar, se falla ___.","opts":["cerrado","abierto","rápido"],"ans":"cerrado"},{"s":"Un resultado vacío sin error es un cero ___.","opts":["sospechoso","correcto","seguro"],"ans":"sospechoso"},{"s":"Una comprobación que nunca dice que no no ___ nada.","opts":["comprueba","cuesta","ocupa"],"ans":"comprueba"}];
const explainQuestions=[{"q":"Explica qué es la frontera de confianza y por qué la validación del navegador no basta.","ans":"La frontera de confianza es la línea donde un dato deja de ser tuyo: lo que se escribe en un formulario, lo que viene en la dirección web, el archivo que sube alguien, la respuesta de un servidor ajeno. Todo lo que la cruza entra como sospechoso hasta que se comprueba. La validación del navegador queda del lado de fuera de esa línea: es cortesía, porque avisa al usuario antes de mandar y ahorra un viaje, pero cualquiera puede saltársela sin abrir siquiera la aplicación, mandando la petición directamente. La comprobación que cuenta es la del servidor, porque es la única que el usuario no puede editar. Regla de la casa: si una comprobación solo existe en el navegador, es como si no existiera."},{"q":"¿Por qué una lista permitida se sostiene y una lista prohibida no?","ans":"La lista prohibida enumera lo que no se acepta, así que solo detiene lo que ya se le ocurrió a alguien: basta una forma nueva de escribir lo mismo (otra codificación, otro espaciado, otro idioma) para pasarla de largo. Y cada vez que aparece un truco nuevo hay que ir a añadirlo, siempre después del daño. La lista permitida enumera lo que sí se acepta y rechaza todo lo demás, y para escribirla no hace falta adivinar el ataque: hace falta conocer el uso legítimo, que es lo único que de verdad se conoce. Si un campo es un grado escolar, la lista permitida son los grados que existen, y con eso queda cerrado sin tener que imaginar nada."},{"q":"Explica qué es una inyección y por qué la consulta con parámetros la evita.","ans":"Una inyección es un dato que termina ejecutándose como una instrucción. Pasa siempre igual: alguien escribe texto donde se esperaba un valor y ese texto acaba dentro de una consulta a la base de datos, dentro de una página web, dentro de una orden de consola o dentro del encargo que se le da a una IA. La causa es una sola, mezclar el dato con la orden, y por eso la solución también es una sola: separarlos. En una consulta con parámetros la instrucción va escrita aparte, con casillas vacías, y el valor viaja en su casilla, así que por raro que venga el texto no puede cambiar la pregunta. Lo mismo en pantalla con textContent en vez de innerHTML: las etiquetas escritas por alguien se ven tal cual y no se ejecutan."},{"q":"¿Qué es fallar en silencio, por qué es el peor fallo y cómo se cazan los ceros sospechosos?","ans":"Fallar en silencio es que una operación salga mal y nadie se entere, porque no hubo error: hubo un resultado vacío. Es el peor fallo porque no deja rastro y porque el sistema sigue diciendo que todo está bien, así que se descubre semanas después, cuando alguien pregunta por qué no llegó nada. El caso de esta casa: la función de las notificaciones leía las suscripciones con la clave anónima, que después de cerrar los datos ya no ve ninguna fila; no dio error, devolvió cero, y las notificaciones del chat murieron sin una sola alarma. Se cazan tratando el cero como pregunta y no como respuesta: si un dato que en un día normal siempre tiene filas devuelve cero, hay que comprobarlo con otro permiso antes de seguir, y si el cero cambia con el permiso, el fallo era de autorización."},{"q":"Explica la diferencia entre autenticar y autorizar con el caso de la política que decía using (true).","ans":"Autenticar responde a «¿quién eres?» y autorizar responde a «¿qué te dejan hacer?». La política del 28 de julio comprobaba lo primero y creía estar comprobando lo segundo: decía que podían leer y escribir los usuarios autenticados, y autenticado no significa «uno de los cuatro de esta casa», significa «cualquiera con una sesión iniciada en este proyecto». Como la clave publicable vive en el navegador, cualquiera podía registrarse con su propio correo, recibir un permiso válido y leerlo y escribirlo todo sin abrir siquiera la aplicación. La política que parecía cerrar la casa la dejaba abierta a quien supiera pedir una cuenta. El arreglo fue comprobar la condición correcta con una función propia que pregunta si quien consulta tiene fila en la tabla de la familia."},{"q":"¿Cómo se sabe que una comprobación de verdad comprueba? Explícalo con el sembrado que decía «Success».","ans":"Se sabe rompiéndola a propósito una vez y viendo que se pone roja de verdad. Una comprobación que nunca ha dicho que no no ha demostrado nada: puede estar mirando el sitio equivocado, puede estar escrita al revés, o puede no poder detener nada aunque vea el problema. Eso último fue lo que pasó con el sembrado de la tabla de la familia: sus tres avisos usaban una forma que solo escribe una nota en un panel lateral y deja seguir, así que el editor mostró un «Success» grande y verde mientras la tabla quedaba vacía. Ninguna de las tres podía decir que no. El arreglo fue que cortaran de verdad, y añadir una cuarta que cuenta las filas al final y se cae si no son exactamente cuatro, que es la que comprueba el resultado y no la intención."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

