const evalTFBank=[{"q":"Todo lo que cruza la frontera de confianza entra como sospechoso hasta que se comprueba.","a":true},{"q":"La validación que hace el navegador es suficiente si el formulario está bien hecho.","a":false},{"q":"Una lista prohibida solo detiene lo que ya se le ocurrió a alguien.","a":true},{"q":"Para escribir una lista permitida hay que adivinar todos los ataques posibles.","a":false},{"q":"Tener sesión iniciada en un proyecto es lo mismo que ser de la familia.","a":false},{"q":"Un límite que no está escrito lo acaba poniendo quien ataca.","a":true},{"q":"La inyección aparece cuando un dato termina ejecutándose como una instrucción.","a":true},{"q":"Quitar del texto las palabras peligrosas es la forma correcta de evitar la inyección.","a":false},{"q":"Con textContent, unas etiquetas escritas por alguien se ven y no se ejecutan.","a":true},{"q":"Una respuesta con código 200 siempre es el archivo que se pidió.","a":false},{"q":"Fallar cerrado es tomar, ante lo que no se puede comprobar, la salida que no hace daño.","a":true},{"q":"Si no hubo error, se puede dar por hecho que la operación salió bien.","a":false},{"q":"Un aviso que va a un panel que nadie mira cuenta como comprobación.","a":false},{"q":"Un cero sin error hay que tratarlo como una pregunta, no como una respuesta.","a":true},{"q":"Una comprobación se puede dar por buena solo cuando ya se la ha visto fallar a propósito.","a":true}];
const evalMCBank=[{"q":"¿Qué entra por la frontera de confianza?","o":["a) Una constante del propio código","b) Lo que escribe alguien en un formulario","c) El número de secciones de la misión","d) Un texto fijo de la interfaz"],"a":1},{"q":"La validación del navegador sirve para…","o":["a) Avisar y ahorrar un viaje, nada más","b) Sustituir la del servidor","c) Cifrar el dato antes de mandarlo","d) Impedir que alguien mande la petición a mano"],"a":0},{"q":"La ventaja de la lista permitida es que…","o":["a) Es más rápida de procesar","b) No hay que adivinar el ataque, solo conocer el uso legítimo","c) No se tiene que actualizar nunca","d) Permite guardar más datos"],"a":1},{"q":"Una política que autoriza a «cualquiera con sesión» está…","o":["a) Bien, porque exige contraseña","b) Comprobando la condición equivocada","c) Bien, si el alta de cuentas está cerrada","d) Mal solo si hay muchos usuarios"],"a":1},{"q":"Un límite razonable para una subida de archivo es…","o":["a) El que quepa en el disco","b) Ninguno, se revisa después","c) Un tope de tamaño y una lista de tipos aceptados","d) Solo comprobar la extensión del nombre"],"a":2},{"q":"La causa de toda inyección es…","o":["a) Mezclar el dato con la instrucción","b) Usar comillas simples","c) No cifrar la base de datos","d) Un servidor mal configurado"],"a":0},{"q":"La consulta con parámetros funciona porque…","o":["a) Limpia el texto de caracteres raros","b) Rechaza los textos muy largos","c) La instrucción va aparte y el dato no puede cambiarla","d) Compara con una lista de ataques"],"a":2},{"q":"Pintar el mensaje del chat con innerHTML permite que…","o":["a) Se vea más ordenado","b) Se pueda copiar el texto","c) Cargue más rápido","d) Se ejecute lo que otro escribió"],"a":3},{"q":"Un service worker debe rechazar una respuesta cuando…","o":["a) Tarda más de un segundo","b) Pesa más de cien kilobytes","c) Viene de un servidor distinto","d) Viene HTML donde se pidió un script, o hubo redirección"],"a":3},{"q":"Si no llega la confirmación de que un documento se guardó, lo correcto es…","o":["a) Borrar el archivo para no dejar basura","b) Volver a subirlo de una vez","c) Preguntar si la ficha existe antes de borrar nada","d) Suponer que falló y avisar de eso"],"a":2},{"q":"Fallar cerrado significa…","o":["a) Cerrar la aplicación al primer error","b) Guardar el error y seguir adelante","c) Reintentar hasta que salga bien","d) Ante lo que no se puede comprobar, tomar la salida que no hace daño"],"a":3},{"q":"Una función que devuelve cero filas y ningún error…","o":["a) Es un cero sospechoso y hay que comprobarlo con otro permiso","b) Está bien: cero es un resultado válido","c) Hay que reintentarla y ya","d) Solo importa si alguien se queja"],"a":0},{"q":"Un aviso que no interrumpe la ejecución es…","o":["a) La forma correcta de comprobar","b) Suficiente si se lee el registro","c) Una comprobación que no puede decir que no","d) Mejor que un error, porque no asusta"],"a":2},{"q":"La forma de creerle a una comprobación es…","o":["a) Romperla a propósito y ver que se pone roja","b) Leerla dos veces con calma","c) Ver que siempre sale en verde","d) Que la escriba otra persona"],"a":0},{"q":"Ante una IA, el texto que llega de fuera se trata como…","o":["a) Instrucción, si viene bien redactado","b) Dato, nunca como orden","c) Contexto de confianza","d) Ejemplo que se puede seguir"],"a":1}];
