function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"La política de seguridad por fila dice que pueden leer y escribir los usuarios autenticados. Parece que cierra la casa, pero el alta de cuentas del proyecto está abierta y la clave publicable vive en el navegador."},{"txt":"El service worker guarda en la caché todo lo que responde con código 200. Detrás de la puerta de Cloudflare, cuando la sesión caduca el servidor devuelve la pantalla de acceso, en HTML y con 200, donde se había pedido js/app.js."},{"txt":"Al subir un documento a la Bóveda falla la respuesta del guardado de la ficha. El código de limpieza borra el archivo del depósito para no dejar basura suelta."},{"txt":"El bloque que siembra los cuatro miembros de la familia avisa con un mensaje si un correo no coincide, pero no interrumpe. El editor muestra «Success» y la tabla queda vacía."},{"txt":"La función que manda las notificaciones del chat lee las suscripciones con la clave anónima. Desde que se cerraron los datos, esa consulta devuelve cero filas y ningún error."},{"txt":"Para saber qué tablas quedaban abiertas se usó la lista de los archivos .sql del repositorio. Cuatro tablas que el código usa de verdad no estaban en esa lista."},{"txt":"Para comprobar que un extraño ya no ve nada se abrió la aplicación en una ventana de incógnito y se inició sesión. No salió ningún dato ajeno y se dio por buena la prueba."},{"txt":"Un formulario de la aplicación acepta un texto libre que después se pega dentro de un mensaje que se le manda a una IA para que lo resuma."}];
const critCaseQuestions=["1. ¿Qué se está dando por cierto sin comprobar, y dónde cruzó ese dato la frontera de confianza?","2. ¿Cuál es la comprobación correcta, y en qué lado (aparato o servidor) tiene que vivir?","3. Escribe en 3-4 frases qué pasa el día que esto falle, y si se va a notar o va a fallar en silencio.","4. ¿Qué se rompe a propósito para saber que el arreglo de verdad comprueba?"];
const critCaseGuides=["Nombrar el dato exacto y de dónde viene. Casi siempre lo que se da por cierto es una condición parecida a la correcta, no una mentira evidente: sesión en vez de familia, código 200 en vez de archivo pedido, ausencia de error en vez de éxito.","La comprobación correcta se escribe como lista permitida y vive donde el usuario no puede editarla. Si la única defensa está en el navegador, no hay defensa.","Lo que decide la gravedad no es el fallo, es si se oye. Un fallo ruidoso se arregla el mismo día; uno silencioso se descubre semanas después y para entonces ya hay daño acumulado.","Una comprobación que nunca ha dicho que no todavía no ha demostrado nada. Se rompe a propósito, se ve la señal roja, se arregla y se ve volver el verde."];

const critErrorBank=[{"txt":"\"La política ya exige estar autenticado, así que la casa está cerrada\".","g1":"Autenticado significa «cualquiera con sesión en este proyecto», no «uno de los cuatro». Con el alta de cuentas abierta, eso es una puerta con letrero, no una puerta.","g2":"Se comprueba la condición correcta: una función propia que pregunta si quien consulta tiene fila en la tabla de la familia, y se aplica en el using y en el with check."},{"txt":"\"Vino con código 200, así que es el archivo que pedí y se puede guardar en la caché\".","g1":"Detrás de una puerta con contraseña, una sesión caducada devuelve la pantalla de acceso en HTML y con 200. Guardar eso como si fuera app.js envenena la aplicación, y recargar no arregla nada.","g2":"Se mira lo que llega, no solo el número: se rechaza si hubo redirección y si viene HTML donde se pidió un script, una hoja de estilo o una imagen."},{"txt":"\"No llegó la confirmación de que se guardó la ficha, así que borro el archivo para no dejar basura\".","g1":"No enterarse no es lo mismo que no pasar. Si la fila entró y lo que se perdió fue la respuesta, ese borrado destruye un documento que estaba bien guardado.","g2":"Primero se pregunta si la ficha existe. Se borra solo cuando se sabe que no hay ficha que reclame el archivo, y si no se puede averiguar, no se borra nada."},{"txt":"\"El bloque avisa si algún correo no coincide, así que si algo falla me voy a enterar\".","g1":"Avisar no es detener. El aviso se va a un panel lateral que casi nadie mira mientras el resultado grande y verde dice «Success», y la tabla se queda vacía.","g2":"Las comprobaciones cortan con error y deshacen la transacción, y al final se cuentan las filas: si no son exactamente cuatro, falla igual."},{"txt":"\"La consulta no dio error, así que las notificaciones están funcionando\".","g1":"No hubo error porque no hubo pregunta mal formada: hubo cero filas. La clave anónima dejó de ver suscripciones al cerrar los datos y las notificaciones murieron sin una sola alarma.","g2":"Se usa la clave de servicio, que corre en el servidor y no baja al navegador, y además se trata el cero como sospecha: cero suscripciones en una casa con cuatro teléfonos no es un resultado, es un aviso."},{"txt":"\"Abrí la aplicación en incógnito, inicié sesión y no vi datos ajenos: está cerrado\".","g1":"Iniciar sesión convierte al que prueba en familia, así que esa prueba no podía salir mal. Una prueba que no puede fallar no prueba nada.","g2":"La prueba es la petición cruda con la clave pública y sin sesión, y tiene que devolver vacío. Y antes de fiarse de ella, se comprueba que con la casa abierta esa misma petición devolvía todo."}];

const critDecisionBank=["La política de la base dice «to authenticated»: ¿qué condición hay que comprobar de verdad y dónde se escribe?","El service worker guarda todo lo que responde 200: ¿qué tres señales delatan a un intruso y cuál basta?","Falló la respuesta al guardar la ficha de un documento: ¿se borra el archivo, se deja o se pregunta antes?","El sembrado dijo «Success» con la tabla vacía: ¿qué se cambia para que no pueda volver a decirlo?","Las notificaciones no llegan y la función no da error: ¿por dónde se empieza a buscar y qué se mira primero?","Hay que saber qué tablas están abiertas: ¿se mira el repositorio o el servidor, y por qué?","Hay que probar que un extraño no ve nada: ¿cómo se hace la prueba para que pueda salir mal?","Un texto que escribe un usuario va a acabar dentro del encargo que se le da a una IA: ¿qué se hace con él?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se nombra el dato que cruza la frontera y de dónde viene; después se escribe la comprobación como lista permitida y se pone del lado del servidor, que es el que el usuario no puede editar; después se decide qué pasa cuando la comprobación no se puede hacer, y ahí se falla cerrado, nunca en silencio; y al final se rompe la comprobación a propósito para ver que de verdad se pone roja. Si el fallo no se puede oír, todavía no está resuelto.';

const critCompareBank=[{"a":"Comprobar que quien consulta tiene fila en la tabla de la familia.","b":"Comprobar que quien consulta tiene una sesión iniciada.","ga":"Caso A: comprueba la condición que de verdad importa, y quien no está en la tabla no ve nada, tenga cuenta o no.","gb":"Caso B: con el alta de cuentas abierta, cualquiera se registra, recibe un permiso válido y lo lee todo sin abrir la aplicación."},{"a":"Rechazar la respuesta que llega con redirección o con HTML donde iba un script.","b":"Guardar en la caché todo lo que responda con código 200.","ga":"Caso A: mira el contenido, no solo el número, así que la pantalla de acceso no se cuela nunca como si fuera la aplicación.","gb":"Caso B: una sesión caducada envenena la caché, y desde el teléfono no hay forma de arreglarlo porque recargar sirve la basura otra vez."},{"a":"Preguntar si la ficha existe antes de borrar el archivo suelto.","b":"Borrar el archivo en cuanto falle la respuesta del guardado.","ga":"Caso A: distingue «no me enteré» de «no pasó», y ante la duda deja el archivo quieto, que es la salida que no destruye nada.","gb":"Caso B: si la fila sí entró y lo que se perdió fue la respuesta, queda una ficha que se ve, se toca y no abre."},{"a":"Que la comprobación corte con error y además cuente el resultado al final.","b":"Que la comprobación deje un aviso y siga adelante.","ga":"Caso A: el fallo se oye el mismo día y la transacción se deshace, así que no queda nada a medias.","gb":"Caso B: el aviso se va a un panel que nadie mira, el resultado sale verde y el problema se descubre mucho después."}];

const critCauseBank=[{"cause":"Se comprueba una condición parecida a la correcta, pero no la correcta.","guide":"Es el fallo que más engaña, porque el código se lee bien: sesión en vez de familia, código 200 en vez de archivo pedido, ausencia de error en vez de éxito."},{"cause":"La única validación vive en el navegador.","guide":"Cualquiera manda la petición directamente y se salta la comprobación sin abrir la aplicación. Lo que no está en el servidor, no está."},{"cause":"El dato del usuario se pega dentro de una instrucción.","guide":"Ahí nace toda inyección, sea una consulta, una página, una orden de consola o el encargo de una IA. La causa es una sola: mezclar dato y orden."},{"cause":"La comprobación avisa pero no interrumpe.","guide":"El aviso se va a un panel lateral, el resultado sale verde y la operación sigue adelante como si nada. Avisar no es comprobar."},{"cause":"Se toma la ausencia de error como prueba de éxito.","guide":"Un cero sin error es la forma más común de fallar en silencio: nada se rompe, nada avisa, y el problema se descubre semanas después."},{"cause":"La prueba se monta de forma que no pueda salir mal.","guide":"Probar la casa cerrada con la sesión iniciada, o dar por buena una comprobación que nunca ha dicho que no. Una prueba que no puede fallar no prueba nada."}];
const critEffectBank=[{"effect":"La aplicación quedó envenenada y recargar no la arreglaba.","guide":"La caché guardó la pantalla de acceso como si fuera un archivo de la aplicación, porque se miró el código 200 y no el contenido."},{"effect":"Las notificaciones del chat dejaron de llegar durante semanas sin una sola alarma.","guide":"La consulta se hizo con un permiso que ya no veía ninguna fila, devolvió cero y nadie trató ese cero como sospechoso."},{"effect":"La tabla quedó vacía mientras el editor mostraba «Success».","guide":"Las comprobaciones solo avisaban, así que ninguna podía detener nada, y no había un recuento final del resultado."},{"effect":"Un documento bien guardado desapareció del depósito.","guide":"La limpieza confundió una respuesta perdida con un guardado fallido y borró antes de preguntar si la ficha existía."},{"effect":"Cuatro tablas siguieron abiertas justo después de dar la casa por cerrada.","guide":"La lista se sacó del repositorio, que dice lo que se pensó, en vez del código y del servidor, que dicen lo que hay."},{"effect":"Se firmó como cerrada una casa que seguía abierta.","guide":"La prueba se hizo con sesión iniciada, así que medía otra cosa. La prueba buena es la que puede salir mal."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El fallo que no se oyó · Forma ${cf} · El código que no confía · Ruta de la Casa Cerrada`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué se está dando por cierto sin comprobar, cuál es la comprobación correcta y en qué lado vive? Explica por qué tu arreglo se va a oír el día que falle, en vez de fallar en silencio.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El fallo que no se oyó: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué se está dando por cierto sin comprobar, cuál es la comprobación correcta y en qué lado vive? Explica por qué tu arreglo se va a oír el día que falle, en vez de fallar en silencio.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El fallo que no se oyó El código que no confía · Ruta de la Casa Cerrada · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El fallo que no se oyó · El código que no confía · Ruta de la Casa Cerrada · Etapa 3 · Ciberseguridad</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El fallo que no se oyó · El código que no confía · Ruta de la Casa Cerrada · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🚧","label":"De dónde viene","text":"La <strong>frontera de confianza</strong>: dónde deja el dato de ser tuyo. <strong>Decide:</strong> qué hay que comprobar. <strong>Se rompe:</strong> al tratar como propio lo que escribió otro. <strong>En F.A.R.O:</strong> el formulario, la dirección, el archivo que se sube y la respuesta de un servidor ajeno."},{"y":"2","icon":"🔍","label":"Qué forma tiene","text":"La <strong>validación</strong>: tipo, largo, formato y rango, contra una <strong>lista permitida</strong>. <strong>Decide:</strong> si el dato entra. <strong>Se rompe:</strong> con listas prohibidas que siempre llegan tarde. <strong>En F.A.R.O:</strong> la Bóveda acepta unos tipos y un tamaño, no cualquier cosa."},{"y":"3","icon":"🪪","label":"Quién lo manda","text":"La <strong>autorización</strong>, comprobada en el servidor. <strong>Decide:</strong> si esa persona puede. <strong>Se rompe:</strong> al confundir tener sesión con ser de la casa. <strong>En F.A.R.O:</strong> es_familia() pregunta por la fila en familia_miembros, no por la sesión."},{"y":"4","icon":"🚧","label":"Cuánto se acepta","text":"El <strong>límite</strong>: tamaño, cantidad, ritmo, tiempo de espera y filas por consulta. <strong>Decide:</strong> hasta dónde puede llegar el daño. <strong>Se rompe:</strong> al no escribirlo. <strong>En F.A.R.O:</strong> sin tope, un archivo llena el depósito de la Bóveda."},{"y":"5","icon":"💉","label":"Dato u orden","text":"La <strong>separación</strong> entre dato e instrucción. <strong>Decide:</strong> si hay inyección. <strong>Se rompe:</strong> al pegar el texto dentro de una consulta, de una página o de un encargo. <strong>En F.A.R.O:</strong> el chat se pinta con textContent a propósito."},{"y":"6","icon":"🔒","label":"Qué pasa si falla","text":"<strong>Fallar cerrado</strong>: la salida que no hace daño. <strong>Decide:</strong> si un fallo se vuelve agujero. <strong>Se rompe:</strong> al borrar, guardar o dejar pasar por si acaso. <strong>En F.A.R.O:</strong> la Bóveda no borra el archivo cuando no puede comprobar si hay ficha."},{"y":"7","icon":"🔔","label":"Se oye o no","text":"El fallo tiene que <strong>hacer ruido</strong>. <strong>Decide:</strong> cuánto tiempo dura el daño. <strong>Se rompe:</strong> con avisos que no interrumpen y con ceros que se dan por buenos. <strong>En F.A.R.O:</strong> las notificaciones murieron en silencio por un cero sin error."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(loComprueba){sfx(loComprueba?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(loComprueba){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🔔</span><span class="ms-text"><strong>Trataste el cero como pregunta:</strong> cero suscripciones en una casa con cuatro teléfonos no es un resultado posible, así que la función se para y avisa en vez de terminar en verde.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔑</span><span class="ms-text"><strong>Y el fallo aparece el mismo día:</strong> la consulta se repite con la clave de servicio, devuelve las cuatro suscripciones y queda claro que el problema era el permiso, no la red. Se arregla en una línea.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🤫</span><span class="ms-text"><strong>Diste el cero por bueno:</strong> no hubo error, así que la función recorre cero teléfonos y termina en verde. Nada se rompe, nada avisa.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📵</span><span class="ms-text"><strong>Y se descubre semanas después:</strong> cuando alguien pregunta por qué no le llega nada del chat. No fue un fallo grande: fue un fallo callado, que es lo que lo hizo caro.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"entrada":{"nombre":"La entrada que llega","icon":"🚧","estructura":{"title":"Qué es","info":"• Todo dato que <strong>cruza la frontera de confianza</strong><br>• Formulario, dirección web, archivo subido, respuesta ajena<br>• Entra como sospechoso hasta que se comprueba"},"funcion":{"title":"Cómo se comprueba","info":"• Contra una <strong>lista permitida</strong>: se escribe lo que sí entra<br>• Tipo, largo, formato y rango, en ese orden<br>• Y siempre <strong>en el servidor</strong>: el navegador es cortesía"},"enfermedades":{"title":"Dónde se rompe","info":"• Con listas prohibidas, que solo paran lo ya conocido<br>• Al fiarse del código 200 sin mirar el contenido<br>• Al tratar como propio lo que en realidad escribió otro"},"cuidados":{"title":"Cómo está en F.A.R.O","info":"• El <strong>service worker</strong> rechaza lo que llega con redirección o con HTML donde iba un script<br>• La <strong>Bóveda</strong> acepta tipos y tamaños concretos<br>• El chat pinta el mensaje con textContent"}},"limite":{"nombre":"El límite","icon":"🚦","estructura":{"title":"Qué es","info":"• <strong>Cuánto, cuántas veces, hasta cuándo y hasta dónde</strong><br>• Tamaño, cantidad, ritmo, tiempo de espera y alcance<br>• Un límite que no se escribe lo acaba poniendo otro"},"funcion":{"title":"Cómo se comprueba","info":"• Se elige un número concreto y se escribe, aunque sea provisional<br>• Se comprueba <strong>antes</strong> de hacer el trabajo, no después<br>• Y el rechazo dice qué pasó, sin contar de más"},"enfermedades":{"title":"Dónde se rompe","info":"• Con la subida sin tope, que llena el depósito<br>• Con la consulta sin paginar, que trae la tabla entera<br>• Con la espera sin corte, que deja la pantalla colgada"},"cuidados":{"title":"Cómo está en F.A.R.O","info":"• La <strong>Bóveda</strong> es donde más se nota: archivos de la familia sin tope es un problema esperando<br>• Y el <strong>límite de intentos</strong> de la puerta es de la etapa 1, no se repite aquí"}},"inyeccion":{"nombre":"Dato u orden","icon":"💉","estructura":{"title":"Qué es","info":"• Un dato que termina <strong>ejecutándose como instrucción</strong><br>• Cuatro caras, una sola causa: consulta, página, consola y encargo a una IA<br>• La causa es mezclar el dato con la orden"},"funcion":{"title":"Cómo se comprueba","info":"• <strong>Consulta con parámetros:</strong> la orden aparte, el dato en su casilla<br>• <strong>textContent</strong> en vez de innerHTML al pintar<br>• Con una IA: decir que lo pegado es dato y nunca instrucción"},"enfermedades":{"title":"Dónde se rompe","info":"• Al armar la consulta pegando el texto del usuario<br>• Al intentar «limpiar» el texto quitando palabras peligrosas<br>• Al meter en el encargo de una IA un correo o un mensaje de fuera"},"cuidados":{"title":"Cómo está en F.A.R.O","info":"• El <strong>chat familiar</strong> pinta usuario, tema y mensaje con textContent, así que unas etiquetas escritas se ven y no se ejecutan<br>• Las consultas van por el cliente de Supabase, con el valor aparte"}},"silencio":{"nombre":"El fallo que no se oye","icon":"🤫","estructura":{"title":"Qué es","info":"• La operación sale mal y <strong>nadie se entera</strong><br>• No hay error: hay un resultado vacío o un aviso que nadie lee<br>• Es el fallo más caro porque dura semanas"},"funcion":{"title":"Cómo se comprueba","info":"• El fallo <strong>corta</strong>, no avisa: error rojo y transacción deshecha<br>• Se cuenta el resultado al final y se falla si no cuadra<br>• El <strong>cero</strong> se trata como pregunta, no como respuesta"},"enfermedades":{"title":"Dónde se rompe","info":"• Con avisos que van a un panel que nadie mira<br>• Al tomar la ausencia de error como prueba de éxito<br>• Con pruebas montadas de forma que no puedan salir mal"},"cuidados":{"title":"Cómo está en F.A.R.O","info":"• Caso real del 28 de julio de 2026: las <strong>notificaciones del chat</strong> murieron por un cero sin error<br>• El sembrado de la familia ya se cae con error rojo y cuenta las cuatro filas<br>• Regla: <strong>si no se puede oír, no está resuelto</strong>"}}};
let labParte='entrada',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🚦 ¡'+name+' completó la Etapa 3 de la Ruta de la Casa Cerrada (El código que no confía)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

